WITH cleaned AS (SELECT *, REGEXP_REPLACE(product_name, ' ', '-') AS product_name_slug FROM products WHERE supplier_id IS NOT NULL) SELECT supplier_id, MAX(cost) FILTER (WHERE brand = 'Acme') AS acme_max_cost, COUNT_IF(brand = 'Globex') AS globex_events, COUNT(*) FILTER (WHERE category = 'Books') AS books_rows FROM cleaned GROUP BY ROLLUP (supplier_id) ORDER BY acme_max_cost DESC NULLS LAST;
